  ('40219f07-8a38-440e-af10-407630f8bfc4', 2023, false, 'pendiente', null, null, null, null, false, null, 'Robert Parker Wine Advocate', null, null, null, null, null, null, null, '[]'::jsonb, 'No se pudo buscar el 08/11/2026: se agotó el cupo de búsquedas y la red bloqueaba las fuentes. Repetir con «Buscar puntuación» en el panel.', 'revision'),
