  ('30df5532-9a6e-4f04-b495-4c5a80a6e22a', 2025, false, 'no_localizada', 'no_localizada', null, null, null, false, null, 'Robert Parker Wine Advocate', null, null, null, null, null, null, '2026-11-08'::date, '[]'::jsonb, 'Búsquedas: ''"Pazo de Señorans" Albariño 2025 Wine Advocate OR Parker'', ''"Pazo Señorans 2025" Albariño Robert Parker'', búsqueda limitada a robertparker.com. Ninguna nota WA para la añada 2025 (añada muy reciente); las tiendas (Vinissimus, Gourmet Hunters, Enterwine) muestran 92 Parker para 2024 y nada de Parker para 2025.', 'revision'),
  ('82498517-d35e-408d-8817-a1ea8817849e', 2015, false, 'revision', 'fuentes_contradictorias', '97', 97, 97, false, '2015 Albariño Selección de Añada (Pazo de Señorans)', 'Robert Parker Wine Advocate', 'Luis Gutiérrez', null, 'Zachys (ficha SKU 577276)', 'https://www.zachys.com/products/577276', 'secundaria', 'Zachys: 97 puntos, Luis Gutiérrez (Robert Parker''s Wine Advocate): the 2015 Albariño Selección de Añada is "nothing short of phenomenal" (fragmento de búsqueda).', '2026-11-08'::date, '[{"fuente_nombre":"Zachys / PJ Wine / Woodland Hills Wine Co. / gute-weine.de","fuente_url":"https://www.zachys.com/products/577276","puntos_texto":"97","nota":"Varias tiendas dan WA 97 para 2015; Bodeboca reproduce la reseña de Gutiérrez (más de 30 meses en depósito con lías, embotellado en junio de 2024, 18.000 botellas)."},{"fuente_nombre":"Gourmet Hunters","fuente_url":"https://www.gourmethunters.hk/en/Pazo+Señorans+Selección+de+Añada+2015","puntos_texto":"96","nota":"Fichas de 2015 en varias versiones del sitio muestran ''Parker Points: 96'' (posible nota de otra añada)."}]'::jsonb, 'Solo fragmentos de búsqueda (Firecrawl sin créditos; robertparker.com y tiendas bloqueadas por la red). En robertparker.com no apareció la ficha en el buscador. La mayoría de fuentes (con crítico y cita) apuntan a 97; Gourmet Hunters da 96.', 'revision'),
