  ('1d2c19d4-9d36-4531-ad0a-4824109b43de', 2002, false, 'revision', 'fuentes_contradictorias', '96', 96, 96, false, '2002 Dom Pérignon P2', 'Robert Parker Wine Advocate', 'William Kelley', '2019-03', 'Fragmentos de búsqueda (Zachys, Morrell Wine, Pogo''s Wine)', 'https://www.zachys.com/products/dom-perignon-p2-2002-750ml', 'secundaria', '96 Points, William Kelley, Robert Parker''s Wine Advocate (Zachys, Dom Pérignon P2 2002); reseña de marzo 2019: ''still a youthful wine, but it is beginning to develop appreciable complexity''', '2026-11-08'::date, '[{"fuente_nombre":"Wine and Cheese Place / Lincoln Fine Wines / zyn.ca","fuente_url":"https://www.wineandcheeseplace.com/wines/Moet-and-Chandon-Dom-Perignon-P2-Plenitude-Brut-2002-w4863652t9","puntos_texto":"95","nota":"Atribuyen ''Wine Advocate: 95 Points'' al P2 2002 (posible reseña anterior de WA, sin fecha ni crítico en el fragmento)."},{"fuente_nombre":"Hedonism","fuente_url":"https://www.hedonism.co.uk/product/dom-perignon-p2-2002","puntos_texto":"95 / 92","nota":"Título ''Robert Parker rating: 95''; la página mezcla varios productos (también aparece 92), poco fiable."}]'::jsonb, 'Fragmentos del buscador web (WebSearch); no se pudo abrir ninguna página (Firecrawl sin créditos y proxy que bloquea tiendas/robertparker.com). Probablemente WA publicó dos reseñas (una de 95, anterior, y la de William Kelley de 96 en mar. 2019), pero no se ha podido confirmar a qué reseña corresponde el 95.', 'revision'),
  ('5f98d412-135b-4f0d-979e-ba7c41162781', 2005, false, 'revision', null, '93', 93, 93, false, '2005 Moët & Chandon Dom Pérignon Rosé', 'Robert Parker Wine Advocate', 'William Kelley', null, 'Fragmentos de búsqueda (J.J. Buckley, Sokolin, Hedonism)', 'https://www.jjbuckley.com/wine/2005-moet-chandon-dom-perignon-rose/2005-862-750/', 'secundaria', '2005 Moet Chandon Dom Perignon Rose ... Robert Parker''s Wine Advocate is more reserved at 93 points, but still clearly positive', '2026-11-08'::date, '[{"fuente_nombre":"Hedonism (magnum 2005)","fuente_url":"https://hedonism.co.uk/product/dom-perignon-rose-magnum-2005","puntos_texto":"93 / 94","nota":"El título dice ''Robert Parker rating: 93'', pero la página mezcla varios productos y también muestra 94 RP; probablemente de otra añada o formato."}]'::jsonb, 'Fuente secundaria vista solo en los resultados del buscador (no se abrió la página): ábrela y, si es correcta, pulsa «Confirmar». Fragmentos del buscador web (WebSearch); no se pudo abrir la página (Firecrawl sin créditos, proxy bloquea tiendas). J.J. Buckley (que atribuye la reseña a William Kelley), Sokolin (''93 RP'') y Hedonism coinciden en 93. Las notas de 99 (Suckling), 96 (Falstaff) y 94 (Vinous) no valen.', 'revision'),
  ('246cd25d-cf75-4eca-b2cb-72d5b5f6fb06', 2013, false, 'revision', null, '95+', 95, 95, false, '2013 Dom Pérignon', 'Robert Parker Wine Advocate', 'William Kelley', '2022-08', 'Fragmentos de búsqueda (Fine Wine Cellar, Liv-ex)', 'https://www.finewinecellar.co.uk/collections/all-wines/products/dom-perignon-2013', 'secundaria', 'William Kelley, Wine Advocate, August 2022 95+ (Fine Wine Cellar, Dom Pérignon 2013); Liv-ex: ''The Wine Advocate''s William Kelley gave the 2013 Dom Pérignon a score of 95+ points.''', '2026-11-08'::date, '[{"fuente_nombre":"Varias tiendas (p. ej. Farr Vintners, Justerini & Brooks)","fuente_url":"https://farrvintners.com/wine.php?preset=3&wine=87999","puntos_texto":"95","nota":"''95 Yohan Castaing, Wine Advocate, April 2023'': segunda reseña WA, misma cifra (95) sin el ''+''. No cambia la cifra."},{"fuente_nombre":"Harvey Nichols","fuente_url":"https://harveynichols.com/dom-perignon/dom-perignon-vintage-champagne-2013-no-box-949427-na-163373","puntos_texto":"94","nota":"Atribuye 94 a WA pero el texto citado es el de Vinous (Galloni): error de la tienda, no vale."}]'::jsonb, 'Fuente secundaria vista solo en los resultados del buscador (no se abrió la página): ábrela y, si es correcta, pulsa «Confirmar». Fragmentos del buscador web (WebSearch); no se pudo abrir la página (Firecrawl sin créditos, proxy bloquea tiendas). WA tiene dos reseñas: William Kelley 95+ (ago. 2022, en el lanzamiento) y Yohan Castaing 95 (abr. 2023). Las dos dan 95 puntos.', 'revision'),
