  ('04d8f2cc-6d4b-4d1a-926c-1078cd1649df', 2022, false, 'revision', 'fuentes_contradictorias', '98+', 98, 98, false, '2022 Tumba del Rey Moro', 'Robert Parker Wine Advocate', 'Luis Gutiérrez', '2025-12', 'Farr Vintners / Fine Wine Cellar (vistos en el resultado del buscador)', 'https://www.farrvintners.com/wine.php?wine=104847', 'secundaria', '[Fragmentos del buscador, página no abierta] ''98+ Luis Gutierrez, Wine Advocate, December 2025'' · ''Luis Gutierrez, Wine Advocate, December 2025 98+'' · ''The 2022 Tumba del Rey Moro is very spicy (ras el hanout)''', '2026-11-08'::date, '[{"fuente_nombre":"Decántalo (resumen del buscador)","fuente_url":"https://www.decantalo.com/us/en/tumba-del-rey-moro.html","puntos_texto":"98","nota":"Tabla con ''98 Parker'' para 2022; probablemente el mismo 98+ sin el signo."},{"fuente_nombre":"Winehouse (resumen del buscador)","fuente_url":"https://www.winehouse.com/product/2022-comando-g-tumba-del-rey-moro-garnacha-sierra-de-gredos-bc4gimn243g8z","puntos_texto":"84","nota":"Muestra ''84 WA'' para la 2022; casi seguro un error de la tienda."}]'::jsonb, 'Ficha ''solo_produccion'', inactiva y sin categoría. Identificado como el paraje de Comando G en Villanueva de Ávila (1.956 botellas, embotellado en febrero de 2025). Las dos fuentes serias (Farr Vintners y Fine Wine Cellar https://www.finewinecellar.co.uk/products/tumba-del-rey-moro-comando-g-2022) dan 98+ de Luis Gutiérrez (dic. 2025); se marca revisión solo por las cifras discrepantes de Decántalo (98) y Winehouse (84). No se pudo abrir ninguna página (Firecrawl sin créditos; red de la sesión bloqueada).', 'revision'),
  ('140d6263-e88b-4616-a237-92ac403c0c2c', 2021, false, 'no_localizada', 'no_localizada', null, null, null, false, null, 'Robert Parker Wine Advocate', null, null, null, null, null, null, '2026-11-08'::date, '[]'::jsonb, 'Ficha solo en producción (sin categoría ni D.O. en la carta). Búsquedas: ''"Finca Rodma" Avizor 2021'', ''"Avizor" Finca Rodma Ribera del Duero Parker OR "Wine Advocate"''. Para 2021 Decántalo solo muestra Atkin 91, Suckling 92, Peñín 93, Decanter 94 (no válidos). La única nota Parker que aparece es ''2019 91 Parker'' en Decántalo (https://www.decantalo.com/no/en/finca-rodma-avizor.html), de otra añada: no aplicable.', 'revision'),
  ('b0d505fe-4988-4e5d-a0df-cf6c061842cc', 2023, false, 'pendiente', null, null, null, null, false, null, 'Robert Parker Wine Advocate', null, null, null, null, null, null, null, '[]'::jsonb, 'No se pudo buscar el 08/11/2026: se agotó el cupo de búsquedas y la red bloqueaba las fuentes. Repetir con «Buscar puntuación» en el panel.', 'revision'),
  ('b84ec812-c14f-4028-831e-5e50991865f3', 2024, false, 'pendiente', null, null, null, null, false, null, 'Robert Parker Wine Advocate', null, null, null, null, null, null, null, '[]'::jsonb, 'No se pudo buscar el 08/11/2026: se agotó el cupo de búsquedas y la red bloqueaba las fuentes. Repetir con «Buscar puntuación» en el panel.', 'revision'),
  ('da4630d5-8e2d-4ab7-a241-94da44d445aa', 2023, false, 'revision', null, '100', 100, 100, false, 'La Faraona 2023', 'Robert Parker Wine Advocate', 'Luis Gutiérrez', null, 'Bodeboca (fichas FR/IT/PT de La Faraona 2023)', 'https://www.bodeboca.fr/vin/faraona-2023', 'secundaria', 'La Faraona 2023, qui a reçu cette millésime 100 points Parker attribués par Luis Gutiérrez', '2026-11-08'::date, '[]'::jsonb, 'Fuente secundaria vista solo en los resultados del buscador (no se abrió la página): ábrela y, si es correcta, pulsa «Confirmar». Cita tomada de fragmentos de búsqueda (WebSearch); no se pudo abrir la página (bodeboca y robertparker.com bloqueados por la red de la sesión y sin créditos de Firecrawl). Varias fuentes independientes coinciden en 100 para la añada 2023: Bodeboca IT/PT (''ha ricevuto 100 punti Parker da Luis Gutiérrez''), Gute Weine (https://www.gute-weine.de/produkt/descendientes-de-j-palacios-bierzo-la-faraona-2023-67296h, ''Parker: 100/100'', 2.220 botellas), Millesima, Gourmet Hunters y Decántalo. Según Bodeboca, Gutiérrez dice que 2023 podría ser la mejor añada desde 1999; nota de botella (embotellado mayo 2025). Ojo: Vinetur (oct-2026) publica 100 puntos para la añada 2024, que es otra cosecha; existe ficha de 2024 en robertparker.com. Solo en producción (sin categoría en la carta).', 'revision'),
  ('f3a262c3-0c98-469c-b71f-3d2a78644689', 2023, false, 'verificada', null, '96', 96, 96, false, 'La Baixada 2023', 'Robert Parker Wine Advocate', 'Luis Gutiérrez', null, 'Bodeboca', 'https://www.bodeboca.com/vino/baixada-2023', 'secundaria', '# La Baixada 2023 … 96 Parker … **The Wine Advocate:** The 2023 La Baixada wine is from a "vinya classificada" … 3,460 bottles were filled in February 2025. Luis Gutiérrez.', '2026-11-08'::date, '[]'::jsonb, 'Ficha de la añada 2023 en Bodeboca: la nota «96 Parker» va junto al texto de The Wine Advocate que nombra expresamente «The 2023 La Baixada» y firma Luis Gutiérrez (nota de botella, embotellado feb-2025). Coincide con el fragmento de búsqueda de Wine Decider (winedecider.com, ''Alvaro Palacios Priorat La Baixada 2023 … Highest rating: WA96''). Existe en robertparker.com la ficha de 2024 (https://www.robertparker.com/wines/6FCzj5CeAvinjuXCm/alvaro-palacios-la-baixada-2024) pero no localicé la URL de la de 2023. Solo en producción (sin categoría en la carta).', 'revision')
  ) as d(vino_id, anada, sin_anada, estado, motivo, puntos_texto, puntos_min, puntos_max, provisional, vino_evaluado, entidad, critico, fecha_valoracion, fuente_nombre, fuente_url, fuente_tipo, cita, fecha_consulta, discrepancias, notas, origen)
 where exists (select 1 from public."Vinos" v where v.id = d.vino_id)
on conflict (vino_id, clave_anada) do nothing;

do $$
declare
  n_pub integer;
  n_ver integer;
  n_rev integer;
  n_nol integer;
begin
  select count(*) into n_pub from public."Vinos" where puntuacion_parker is not null;
  select count(*) filter (where estado = 'verificada'), count(*) filter (where estado = 'revision'),
         count(*) filter (where estado = 'no_localizada')
    into n_ver, n_rev, n_nol
    from public.vinos_puntuacion_parker where origen = 'revision';
  raise notice 'vinos_puntuacion_parker_revision_datos: % verificadas, % en revisión, % no localizadas; % vinos con puntuación en la web',
    n_ver, n_rev, n_nol, n_pub;
end
$$;

